package com.geekmall.search;import com.geekmall.common.api.ApiResponse;import com.geekmall.common.security.AuthPrincipal;import jakarta.servlet.http.HttpServletRequest;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") class SearchController{private final SearchService s;SearchController(SearchService s){this.s=s;}@GetMapping("/search/products")ApiResponse<Map<String,Object>>search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long categoryId,@RequestParam(required=false)List<Long>brandIds,@RequestParam(required=false)Long shopId,@RequestParam(required=false)Double priceMin,@RequestParam(required=false)Double priceMax,@RequestParam(defaultValue="comprehensive")String sort,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@AuthenticationPrincipal AuthPrincipal p,HttpServletRequest r){return ok(s.search(keyword,categoryId,brandIds,shopId,priceMin,priceMax,sort,page,pageSize,p),r);}@GetMapping("/search/suggestions")ApiResponse<List<String>>suggest(@RequestParam String keyword,HttpServletRequest r){return ok(s.suggest(keyword),r);}@GetMapping("/search/hot-words")ApiResponse<List<Map<String,Object>>>hot(HttpServletRequest r){return ok(s.hot(),r);}@PostMapping("/admin/search/reindex")@PreAuthorize("hasRole('SYSTEM_ADMIN')")ApiResponse<Map<String,Object>>reindex(HttpServletRequest r){return ok(s.reindex(),r);}@PostMapping("/admin/search/dead-letters/replay")@PreAuthorize("hasRole('SYSTEM_ADMIN')")ApiResponse<Map<String,Integer>>replay(HttpServletRequest r){return ok(Map.of("replayed",s.replayDeadLetters()),r);}@GetMapping("/admin/search/reconciliations")@PreAuthorize("hasRole('SYSTEM_ADMIN')")ApiResponse<List<Map<String,Object>>>logs(HttpServletRequest r){return ok(s.reconcileLogs(),r);}private static<T>ApiResponse<T>ok(T d,HttpServletRequest r){return ApiResponse.success(d,String.valueOf(r.getAttribute("requestId")));}}
